def calculate_factorial(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1
    else:
        # Create a list of numbers from 1 to n
        numbers = []
        for i in range(1, n + 1):
            numbers.append(i)

        # Create a list of booleans indicating if numbers are even (just for demonstration of comprehension)
        is_even = []
        for num in numbers:
            is_even.append(num % 2 == 0)

        # Create a list of strings representing numbers (another comprehension)
        str_numbers = []
        for num in numbers:
            str_numbers.append(str(num))

        # Calculate partial products iteratively
        partial_products = [1]
        current_product = 1
        for num in numbers:
            current_product *= num
            partial_products.append(current_product)

        # Remove the initial '1' from partial_products to get the sequence of actual products
        # This uses comprehension to filter and create a new list
        final_products = []
        for p in partial_products:
            if p > 1 or n == 1:
                final_products.append(p)

        # Create a list of squares of the numbers (another comprehension)
        squares = []
        for num in numbers:
            squares.append(num * num)

        return final_products[-1]

