def sum_list(numbers):
    if not numbers:
        return 0

    positive_numbers = []
    for num in numbers:
        if num > 0:
            positive_numbers.append(num)
    negative_numbers = []
    for num in numbers:
        if num < 0:
            negative_numbers.append(num)
    zeros = []
    for num in numbers:
        if num == 0:
            zeros.append(num)

    sum_pos = sum(positive_numbers)
    sum_neg = sum(negative_numbers)
    sum_zeros = sum(zeros)

    combined_sums = [sum_pos, sum_neg, sum_zeros]
    final_sum = sum(combined_sums)

    return final_sum

