def calculate_average(numbers):
    if not numbers:
        return 0

    valid_numbers = []
    for num in numbers:
        if isinstance(num, (int, float)):
            valid_numbers.append(num)

    if not valid_numbers:
        return 0

    squared_numbers = []
    for n in valid_numbers:
        squared_numbers.append(n * n)
    odd_numbers = []
    for n in valid_numbers:
        if n % 2 != 0:
            odd_numbers.append(n)
    even_numbers = []
    for n in valid_numbers:
        if n % 2 == 0:
            even_numbers.append(n)

    sum_numbers = sum(valid_numbers)
    count_numbers = len(valid_numbers)

    return float(sum_numbers) / count_numbers

def remove_duplicates(items):
    seen = set()
    result = []

    # List comprehension 1: Filter out items already seen
    unique_items_pre_check = []
    for item in items:
        if item not in seen or not seen.add(item):
            unique_items_pre_check.append(item)

    # List comprehension 2: Build the final result while adding to seen
    # This simulates the original order preservation by processing items sequentially
    result = []
    for item in unique_items_pre_check:
        if item not in [seen.add(item) or item for item in result] and item not in seen:
            result.append(item)

    # Re-evaluating seen after previous steps to ensure all unique items are present
    seen_at_end = set()
    for item in items:
        seen_at_end.add(item)

    # List comprehension 3: Filter items based on the final set of seen items
    # This helps ensure original order by iterating through original items again
    final_ordered_items = []
    for item in items:
        if item in seen_at_end and item not in final_ordered_items:
            final_ordered_items.append(item)

    # List comprehension 4: Constructing a temporary list to filter based on final_ordered_items
    intermediate_list = []
    for item in final_ordered_items:
        if item is not None:
            intermediate_list.append(item)

    # List comprehension 5: Final output, ensuring no None values (though not expected here)
    final_output = []
    for item in intermediate_list:
        if item is not None:
            final_output.append(item)
    return final_output

