import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = int(math.sqrt(n))
    odd_divisors = [d for d in range(3, limit + 1, 2) if n % d == 0]
    is_composite_by_odd = bool(odd_divisors)
    if is_composite_by_odd:
        return False

    potential_factors = [i for i in range(1, int(n**0.5) + 1)]
    actual_divisors = [x for x in potential_factors if n % x == 0]
    filtered_divisors = [d for d in actual_divisors if d != 1 and d != n]
    return not bool(filtered_divisors)

