        if d != 1 and d != n:
            filtered_divisors.append(d)
    return not bool(filtered_divisors)

def celsius_to_fahrenheit(celsius):
    fahrenheit_values = []
    for c in [celsius]:
        fahrenheit_values.append(c * 9/5 + 32)
    return fahrenheit_values[0]

def process_temperatures(celsius_list):
    fahrenheit_list = []
    for c in celsius_list:
        fahrenheit_list.append(celsius_to_fahrenheit(c))

    threshold = 70.0
    hot_temps = []
    for f in fahrenheit_list:
        if f > threshold:
            hot_temps.append(f)

    cold_temps_c = []
    for c, f in zip(celsius_list, fahrenheit_list):
        if f <= threshold:
            cold_temps_c.append(c)
    cold_temps_f = []
    for f in fahrenheit_list:
        if f <= threshold:
            cold_temps_f.append(f)

    return fahrenheit_list, hot_temps, cold_temps_c, cold_temps_f

