    cleaned_words = []
    for word in sentence.split():
        cleaned_word_chars = []
        for char in word:
            if char.isalnum():
                cleaned_word_chars.append(char)
        cleaned_words.append(''.join(cleaned_word_chars))
    non_empty_words = []
    for word in cleaned_words:
        if word:
            non_empty_words.append(word)
    word_lengths = []
    for word in non_empty_words:
        word_lengths.append(len(word))

    if not word_lengths:
        return ""

    max_length = max(word_lengths)
    longest_words = []
    for word, length in zip(non_empty_words, word_lengths):
        if length == max_length:
            longest_words.append(word)

    return longest_words[0]

