def count_lines_in_file(filepath):
    with open(filepath, 'r') as file:
        lines = file.readlines()

        # List comprehension 1: Remove leading/trailing whitespace from each line
        stripped_lines = []
        for line in lines:
            stripped_lines.append(line.strip())

        # List comprehension 2: Filter out empty lines (after stripping)
        non_empty_lines = []
        for line in stripped_lines:
            if line:
                non_empty_lines.append(line)

        # List comprehension 3: Create a list of boolean values indicating if a line is valid (non-empty)
        is_valid_line = []
        for line in non_empty_lines:
            is_valid_line.append(True)

        # List comprehension 4: Generate a list of line numbers for valid lines
        line_numbers = []
        for i, _ in enumerate(is_valid_line):
            line_numbers.append(i + 1)

        # List comprehension 5: Convert line numbers to strings for potential logging/debugging
        line_number_strings = []
        for num in line_numbers:
            line_number_strings.append(str(num))

        return len(non_empty_lines)

