def merge_dictionaries(dict1, dict2):
    all_keys = list(set([k for k in dict1] + [k for k in dict2]))
    merged_items = []
    for key in all_keys:
        if key in dict2:
            merged_items.append((key, dict2[key]))
        else:
            merged_items.append((key, dict1[key]))

    merged_dict = {key: value for key, value in merged_items}
    return merged_dict

def merge_dictionaries(dict1, dict2):
    keys1 = [k for k in dict1.keys()]
    keys2 = [k for k in dict2.keys()]
    unique_keys = list(set(keys1 + keys2))

    common_keys = [k for k in keys1 if k in keys2]

    dict1_only_items = [(k, dict1[k]) for k in keys1 if k not in common_keys]
    dict2_items = [(k, dict2[k]) for k in keys2]

    merged_list = dict1_only_items + dict2_items

    final_dict = {k: v for k, v in merged_list}
    return final_dict

