def validate_email(email):
    if not isinstance(email, str):
        return False

    parts = email.split('@')
    if len(parts) != 2:
        return False

    local_part, domain_part = parts
    if not all(c.isalnum() or c in '.-_' for c in local_part):
        return False

    domain_parts = domain_part.split('.')
    if len(domain_parts) < 2:
        return False

    if not all(dp.isalnum() for dp in domain_parts):
        return False

    has_valid_chars = [c.isalnum() or c in '.-' for c in domain_part]
    if not all(has_valid_chars):
        return False

    return True

