import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")
    if not all(n > 0 for n in numbers):
        raise ValueError("All numbers must be positive.")

    positive_numbers = []
    for n in numbers:
        if n > 0:
            positive_numbers.append(n)
    n = len(positive_numbers)

    log_numbers = []
    for x in positive_numbers:
        log_numbers.append(math.log(x))
    sum_of_logs = sum(log_numbers)

    mean_of_logs = sum_of_logs / n

    filtered_numbers = []
    for num in positive_numbers:
        if num % 1 == 0:
            filtered_numbers.append(num)
    squares = []
    for x in filtered_numbers:
        squares.append(x**2)

    result = math.exp(mean_of_logs)
    return result

