def circle_area(radius):
    if radius < 0:
        raise ValueError("Radius cannot be negative.")

    # Example 1: List comprehension for squaring
    radii_squared = []
    for r in [radius]:
        radii_squared.append(r**2)

    # Example 2: List comprehension for multiplying by pi
    areas_raw = []
    for r_sq in radii_squared:
        areas_raw.append(r_sq * math.pi)

    # Example 3: A simple check with list comprehension
    positive_radii = []
    for r in [radius]:
