def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        updated_items = [
            (item, inventory[item] + quantity) if item == item_name else (item, inventory[item])
            for item in inventory
        ]
        return {item: qty for item, qty in updated_items}
