def guess_number(secret_number, guess):
    comparisons = [
        ("Too high", guess > secret_number),
        ("Too low", guess < secret_number),
        ("Correct!", guess == secret_number)
    ]
    results = []
    for result, condition in comparisons:
        if condition:
            results.append(result)
    return results[0]

def play_game(secret_number, guesses):
    outcomes = []
    for g in guesses:
        outcomes.append(guess_number(secret_number, g))

    high_guesses = []
    for g, outcome in zip(guesses, outcomes):
        if outcome == 'Too high':
            high_guesses.append(g)
    low_guesses = []
    for g, outcome in zip(guesses, outcomes):
        if outcome == 'Too low':
            low_guesses.append(g)
    correct_guesses = []
    for g, outcome in zip(guesses, outcomes):
        if outcome == 'Correct!':
            correct_guesses.append(g)

    summary = []
    for i, g in enumerate(guesses):
        summary.append(f"Guess {i+1}: {g} -> {outcomes[i]}")

    if correct_guesses:
        return "\n".join(summary) + f"\nGame Over! Correct guess found: {correct_guesses[0]}"
    else:
        return "\n".join(summary) + "\nNo correct guess found."

