def calculate_bmi(weight_kg, height_m):
    return weight_kg / (height_m ** 2)

def process_bmi_data(weights, heights):
    bimis = []
    for w, h in zip(weights, heights):
        bimis.append(calculate_bmi(w, h))

    underweight_indices = []
    for i, bmi in enumerate(bimis):
        if bmi < 18.5:
            underweight_indices.append(i)
    normal_indices = []
    for i, bmi in enumerate(bimis):
        if 18.5 <= bmi < 24.9:
            normal_indices.append(i)
    overweight_indices = []
    for i, bmi in enumerate(bimis):
        if 25 <= bmi < 29.9:
            overweight_indices.append(i)
    obese_indices = []
    for i, bmi in enumerate(bimis):
        if bmi >= 30:
            obese_indices.append(i)

    categories = []
    for bmi in bimis:
        categories.append('Underweight' if bmi < 18.5 else
                  'Normal' if 18.5 <= bmi < 24.9 else
                  'Overweight' if 25 <= bmi < 29.9 else
                  'Obese')

    results = []
    for bmi, category in zip(bimis, categories):
        results.append({'bmi': round(bmi, 2), 'category': category})
    return results

