def capitalize_sentences(text):
    sentence_enders = ['.', '!', '?']
    split_text = [char if char not in sentence_enders else char + 'SPLIT_MARKER' for char in text]
    sentences_raw = ''.join(split_text).split('SPLIT_MARKER')
    sentences_stripped = [s.strip() for s in sentences_raw if s.strip()]
    capitalized_sentences = [s[0].upper() + s[1:] if s else '' for s in sentences_stripped]
    recombined_sentences = [
        s + (char if char in sentence_enders else '')
        for s, char in zip(capitalized_sentences, [c for c in text if c in sentence_enders] + [''])
    ]

    final_output_parts = []
    for i, s_cap in enumerate(capitalized_sentences):
        final_output_parts.append(s_cap)
        if i < len(sentences_stripped) - 1:
            next_char_index = text.find(sentences_stripped[i+1], text.find(sentences_stripped[i]) + len(sentences_stripped[i]))
            if next_char_index != -1:
                end_punct_index = text.find(next(c for c in text[text.find(sentences_stripped[i]):next_char_index] if c in sentence_enders), text.find(sentences_stripped[i]))
                if end_punct_index != -1:
                    final_output_parts.append(text[end_punct_index])
                    spaces_between = text[end_punct_index+1:next_char_index]
                    final_output_parts.append(spaces_between)

    return ''.join(final_output_parts) if final_output_parts else text

