def simulate_queue(operations):
    queue = []

    enqueue_ops = []
    for op in operations:
        if op[0] == 'enqueue':
            enqueue_ops.append(op)
    dequeue_count = sum(1 for op in operations if op[0] == 'dequeue')

    initial_enqueues = []
    for _, item in enqueue_ops:
        initial_enqueues.append(item)
    queue.extend(initial_enqueues)

    for _ in range(dequeue_count):
        if queue:
            queue.pop(0)

    remaining_elements = []
    for element in queue:
        remaining_elements.append(element)

    final_queue_state = []
    for x in remaining_elements:
        final_queue_state.append(x)

    return final_queue_state

def extract_hashtags(text):
    words = text.split()
    hashtag_words = []
    for word in words:
        if word.startswith('#'):
            hashtag_words.append(word)
    cleaned_hashtags = []
    for hashtag in hashtag_words:
        cleaned_hashtags.append(hashtag[1:])
    filtered_hashtags = []
    for ht in cleaned_hashtags:
        if all(c.isalnum() for c in ht):
            filtered_hashtags.append(ht)
    unique_hashtags = sorted(list(set(filtered_hashtags)))
    return unique_hashtags

def list_of_squares(n):
    if n <= 0:
        return []

    numbers = []
    for i in range(1, n + 1):
        numbers.append(i)
    squared_numbers = []
    for x in numbers:
        squared_numbers.append(x * x)

    # Example of another list comprehension for a different purpose: 
    # filtering even numbers before squaring
    even_numbers = []
    for num in range(1, n + 1):
        if num % 2 == 0:
            even_numbers.append(num)
    # Another example: creating strings
    str_numbers = []
    for x in numbers:
        str_numbers.append(str(x))
    # Yet another example: creating tuples
    number_and_square_tuples = []
    for x in numbers:
        number_and_square_tuples.append((x, x*x))

    return squared_numbers

