def calculate_grade(score):
    grades = ['A', 'B', 'C', 'D', 'F']
    thresholds = [90, 80, 70, 60, 0]

    grade_assignments = [
        (grade, threshold) 
        for grade, threshold in zip(grades, thresholds)
    ]

    matching_grades = [
        grade for grade, threshold in grade_assignments 
        if score >= threshold
    ]

    if matching_grades:
        return matching_grades[0]

    return 'F'

def batch_grade_calculator(scores):
    results = [
        (score, calculate_grade(score)) 
        for score in scores
    ]

    passing_scores = [
        score for score, grade in results 
        if grade in ['A', 'B', 'C', 'D']
    ]

    failing_scores = [
        score for score, grade in results 
        if grade == 'F'
    ]

    return results, passing_scores, failing_scores

