def calculate_grade(score):
    grades = ['A', 'B', 'C', 'D', 'F']
    thresholds = [90, 80, 70, 60, 0]

    grade_assignments = []
    for grade, threshold in zip(grades, thresholds):
        grade_assignments.append((grade, threshold))

    matching_grades = []
    for grade, threshold in grade_assignments:
        if score >= threshold:
            matching_grades.append(grade)

    if matching_grades:
        return matching_grades[0]

    return 'F'

def batch_grade_calculator(scores):
    results = []
    for score in scores:
        results.append((score, calculate_grade(score)))

    passing_scores = []
    for score, grade in results:
        if grade in ['A', 'B', 'C', 'D']:
            passing_scores.append(score)

    failing_scores = []
    for score, grade in results:
        if grade == 'F':
            failing_scores.append(score)

    return results, passing_scores, failing_scores

def parse_csv_line(line):
    tokens = []
    for token in line.split(','):
        tokens.append(token.strip())

    result = []
    for token in tokens:
        if token:
            result.append(token)
    return result

def process_csv_data(csv_data):
    all_rows = []
    for row in csv_data.strip().split('\n'):
        if row.strip():
            all_rows.append(parse_csv_line(row))

    cleaned_rows = []
    for row in all_rows:
        inner_list = []
        for value in row:
            inner_list.append(value.strip())
        cleaned_rows.append(inner_list)

    valid_rows = []
    for row in cleaned_rows:
        if row:
            valid_rows.append(row)

    non_empty_values = []
    for row in valid_rows:
        inner_list = []
        for val in row:
            if val:
                inner_list.append(val)
        non_empty_values.append(inner_list)

    uppercase_values = []
    for row in non_empty_values:
        inner_list = []
        for val in row:
            inner_list.append(val.upper())
        uppercase_values.append(inner_list)
    return uppercase_values

