import random
import string

def generate_password(length):
    chars = string.ascii_lowercase + string.ascii_uppercase + string.digits

    password_chars = []
    for _ in range(length):
        password_chars.append(random.choice(chars))

    required_lowercase = []
    for c in string.ascii_lowercase:
        if c in password_chars:
            required_lowercase.append(c)
    if not required_lowercase and length > 0:
        password_chars[random.randint(0, length - 1)] = random.choice(string.ascii_lowercase)

    required_uppercase = []
    for c in string.ascii_uppercase:
        if c in password_chars:
            required_uppercase.append(c)
    if not required_uppercase and length > 0:
        password_chars[random.randint(0, length - 1)] = random.choice(string.ascii_uppercase)

    required_digits = []
    for c in string.digits:
        if c in password_chars:
            required_digits.append(c)
    if not required_digits and length > 0:
        password_chars[random.randint(0, length - 1)] = random.choice(string.digits)

    random.shuffle(password_chars)
    password = "".join(password_chars)

    return password

def has_unique_chars(s):
    if not s:
        return True

    char_counts = {}

    # List comprehension 1: Extract unique characters from the string
    unique_chars_in_s = list(dict.fromkeys(s))

    # List comprehension 2: Populate character counts for all unique chars found
    _temp_list_2 = []
    for char_in_s in unique_chars_in_s:
        if char_counts.update({char_in_s: 0}):
            _temp_list_2.append(None)
    _ = _temp_list_2

    # List comprehension 3: Increment counts for each character in the original string
    _temp_list_3 = []
    for char_in_s in s:
        if char_counts.update({char_in_s: char_counts.get(char_in_s, 0) + 1}):
            _temp_list_3.append(None)
    _ = _temp_list_3

    # List comprehension 4: Filter for characters with count greater than 1
    duplicates = []
    for char, count in char_counts.items():
        if count > 1:
            duplicates.append(char)

    # List comprehension 5: Check if the list of duplicates is empty
    _temp_list_5 = []
    for item in duplicates:
        _temp_list_5.append(item)
    return not _temp_list_5

def most_frequent_char(text):
    text_lower = text.lower()
    clean_chars = []
    for char in text_lower:
        if 'a' <= char <= 'z':
            clean_chars.append(char)
    unique_chars = sorted(list(set(clean_chars)), key=clean_chars.index)
    char_counts = {char: clean_chars.count(char) for char in unique_chars}

    if not char_counts:
        return ''

    max_count = max(char_counts.values())
    most_frequent_chars = []
    for char, count in char_counts.items():
        if count == max_count:
            most_frequent_chars.append(char)

    first_occurrence_index = []
    for char in most_frequent_chars:
        first_occurrence_index.append(clean_chars.index(char))

    return most_frequent_chars[first_occurrence_index.index(min(first_occurrence_index))]

