        header_row.append(i + 1)
    table_rows = []
    for i in range(1, n + 1):
        current_row = []
        for j in header_row:
            current_row.append(i * j)
        table_rows.append(current_row)

    formatted_rows = []
    for row in table_rows:
        formatted_rows.append(" ".join(map(str, row)))

    max_lens = []
    for col in zip(*table_rows):
        inner_list = []
        for item in col:
            inner_list.append(len(str(item)))
        max_lens.append(max(inner_list))

    padded_rows = []
    for row in table_rows:
        inner_list = []
        for idx, item in enumerate(row):
            inner_list.append(str(item).rjust(max_lens[idx]))
        padded_rows.append(inner_list)

    printed_table = []
    for padded_row in padded_rows:
        printed_table.append(" ".join(padded_row))
    for line in printed_table:
        print(line)

    return table_rows

