def find_second_largest(numbers):
    unique_numbers = sorted(list(set(numbers)))
    if len(unique_numbers) < 2:
        raise ValueError("List must contain at least two distinct elements.")

    all_pairs = [[x, y] for x in unique_numbers for y in unique_numbers if x != y]
    sorted_pairs = sorted(all_pairs, key=lambda p: p[0])

    largest_elements = [p[0] for p in sorted_pairs if p[0] == unique_numbers[-1]]
    second_largest_candidates = [p[0] for p in sorted_pairs if p[0] != largest_elements[0]]

    if not second_largest_candidates:
        return unique_numbers[0] # This case shouldn't be reached if len(unique_numbers) >= 2

    return max(second_largest_candidates)

