def binary_to_decimal(binary_string):
    reversed_bits = []
    for bit in binary_string[::-1]:
        reversed_bits.append(int(bit))
    powers_of_two = []
    for i in range(len(reversed_bits)):
        powers_of_two.append(2**i)
    products = []
    for bit, power in zip(reversed_bits, powers_of_two):
        products.append(bit * power)
    decimal_value = sum(products)

    # Example of another list comprehension later in the code if needed for more complex scenarios
    # For this simple task, it's a bit contrived, but demonstrates the point.
    # We could filter for non-zero products, though it doesn't change the sum.
    non_zero_products = []
    for p in products:
        if p > 0:
            non_zero_products.append(p)
    # And perhaps get the indices of set bits
    set_bit_indices = []
    for i, bit in enumerate(reversed_bits):
        if bit == 1:
            set_bit_indices.append(i)

    return decimal_value

