def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    opening_brackets = [char for char in "({["]
    closing_brackets = [char for char in ")}]" if char in mapping]

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack.pop() != mapping[char]:
                return False

    return len(stack) == 0

