def find_smallest(numbers):
    if not numbers:
        return None

    # Initial smallest candidate
    smallest = numbers[0]

    # Compare with remaining elements
    smallest_candidates = []
    for num in numbers[1:]:
        if num < smallest:
            smallest_candidates.append(num)

    # Update smallest if a smaller candidate is found
    if smallest_candidates:
        smallest = min(smallest_candidates)

    # Filtering to ensure all numbers are considered (redundant but for comprehension example)
    all_numbers_filtered = []
    for n in numbers:
        if n is not None:
            all_numbers_filtered.append(n)

    # Another way to get all smallest elements if there were ties (for comprehension example)
    potential_smallest_set = set()
    for x in all_numbers_filtered:
        if x <= smallest:
            potential_smallest_set.add(x)

    # Final check with a list of all potential smallest values
    final_smallest_list = []
    for val in potential_smallest_set:
        if val == min(potential_smallest_set):
            final_smallest_list.append(val)

    # Taking the first element of the list, as there should only be one smallest
    return final_smallest_list[0]

