def simulate_stack(stack, operation, item=None):
    if operation == 'push':
        new_stack = []
        for x in stack:
            new_stack.append(x)
        new_stack = new_stack + [item]
        return new_stack
    elif operation == 'pop':
        if not stack:
            return None
        popped_item = stack[-1]
        remaining_stack = []
        for i in range(len(stack) - 1):
            remaining_stack.append(stack[i])
        stack[:] = remaining_stack
        return popped_item

