def weighted_average(values, weights):
    if not values:
        return 0.0

    products = []
    for v, w in zip(values, weights):
        products.append(v * w)
    sum_products = sum(products)

    positive_weights = []
    for w in weights:
        if w > 0:
            positive_weights.append(w)

    if not positive_weights:
        return 0.0

    valid_indices = []
    for i, w in enumerate(weights):
        if w > 0:
            valid_indices.append(i)

    filtered_values = []
    for i in valid_indices:
        filtered_values.append(values[i])
    filtered_weights = []
    for i in valid_indices:
        filtered_weights.append(weights[i])

    if not filtered_weights:
        return 0.0

    sum_weights = sum(filtered_weights)

    if sum_weights == 0:
        return 0.0

    normalized_products = []
    for v, w in zip(filtered_values, filtered_weights):
        normalized_products.append(v * w)

    return sum(normalized_products) / sum_weights

