def sort_digits(number):
    s = str(abs(number))
    sorted_chars = sorted(list(s))
    non_zero_chars = []
    for c in sorted_chars:
        if c != '0':
            non_zero_chars.append(c)
    zero_chars = []
    for c in sorted_chars:
        if c == '0':
            zero_chars.append(c)

    if not non_zero_chars and zero_chars:
        return 0

    leading_digit = non_zero_chars[0] if non_zero_chars else ''
    remaining_digits = []
    for c in non_zero_chars[1:]:
        remaining_digits.append(c)

    result_chars = [leading_digit] + zero_chars + remaining_digits
    result_str = "".join(result_chars)

    return int(result_str) if result_str else 0

