def flatten_dict(nested_dict, separator):
    flattened_pairs = []

    for k, v in nested_dict.items():
        if isinstance(v, dict):
            nested_keys = [f"{k}{separator}{sub_k}" for sub_k in v.keys()]
            nested_values = [sub_v for sub_v in v.values()]
            flattened_pairs.extend(list(zip(nested_keys, nested_values)))
