def hex_to_decimal(hex_string):
    hex_digits = '0123456789ABCDEF'
    digit_values = {char: i for i, char in enumerate(hex_digits)}
    reversed_hex = hex_string[::-1]

    decimal_values = []
    for char in reversed_hex:
        decimal_values.append(digit_values[char])
    powers_of_16 = []
    for i in range(len(reversed_hex)):
        powers_of_16.append(16**i)

    products = []
    for val, power in zip(decimal_values, powers_of_16):
        products.append(val * power)

    decimal_sum = sum(products)

    return decimal_sum

