        digits.append(int(d))
    reversed_digits = digits[::-1]

    doubled_evens = []
    for i, d in enumerate(reversed_digits):
        if i % 2 == 1:
            doubled_evens.append(d * 2)
        else:
            doubled_evens.append(d)

    sum_of_digits = []
    for d in doubled_evens:
        if d > 9:
            sum_of_digits.append(d - 9)
        else:
            sum_of_digits.append(d)

    total_sum = sum(sum_of_digits)

    return total_sum % 10 == 0

