def fibonacci_sequence(n):
    if n <= 0:
        return []
    if n == 1:
        return [0]

    fib = [0, 1]
    while fib[-1] + fib[-2] < n:
        fib.append(fib[-1] + fib[-2])

    squared_fibs = []
    for x in fib:
        squared_fibs.append(x * x)
    even_fibs = []
    for x in fib:
