    cols_a = len(matrix_a[0])
    rows_b = len(matrix_b)
    cols_b = len(matrix_b[0])

    result_matrix = []
    for _ in range(rows_a):
        row = []
        for _ in range(cols_b):
            row.append(0)
        result_matrix.append(row)

    indices_i = []
    for i in range(rows_a):
        indices_i.append(i)
    indices_j = []
    for j in range(cols_b):
