def calculate_sma(data, window_size):
    if window_size <= 0:
        raise ValueError("Window size must be positive.")
    if len(data) < window_size:
        return []

    # List comprehension 1: Generate all possible window slices
    windows = []
    for i in range(len(data) - window_size + 1):
        windows.append(data[i:i + window_size])

    # List comprehension 2: Calculate the sum for each window
    window_sums = []
    for window in windows:
        window_sums.append(sum(window))

    # List comprehension 3: Calculate the average for each window
    sma_values = []
    for current_sum in window_sums:
        sma_values.append(current_sum / window_size)

    # List comprehension 4: Convert any resulting integers to floats (if input data was all integers)
    # This ensures consistency as per the example output format (e.g., 2.0 instead of 2)
    float_sma_values = []
    for val in sma_values:
        float_sma_values.append(float(val))

    # List comprehension 5: Filter out any potential non-numeric results (though unlikely with current logic)
    # This acts as a final type check and ensures only valid floats are returned.
    filtered_sma_values = []
    for val in float_sma_values:
        if isinstance(val, (int, float)):
            filtered_sma_values.append(val)

    return filtered_sma_values

