    reversed_bits = []
    for bit in reversed(binary_string):
        reversed_bits.append(int(bit))

    powers_of_two = []
    for i in range(n):
        powers_of_two.append(2**i)

    multiplied_terms = []
    for bit, power in zip(reversed_bits, powers_of_two):
        multiplied_terms.append(bit * power)

    decimal_value = sum(multiplied_terms)

    # Another example of list comprehension for fun, not directly part of the core logic
