def calculate_discount_price(original_price, discount_percentage):
    prices = [original_price]
    discount_rates = [discount_percentage / 100]
    discounts = []
    for price in prices:
        for rate in discount_rates:
            discounts.append(price * rate)
    final_prices_intermediate = []
    for price in prices:
        for discount in discounts:
            final_prices_intermediate.append(price - discount)
