    for uk, tv in zip(uppercase_keys, transformed_values):
        combined_pairs.append((uk, tv))

    original_keys = []
    for item in sorted_items:
        original_keys.append(item[0])
    original_values = []
    for item in sorted_items:
        original_values.append(item[1])

    return OrderedDict(zip(original_keys, original_values))

