    char_list = [char for char in input_string]
    reversed_char_list = [char_list[i] for i in range(len(char_list) - 1, -1, -1)]

    vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']
    consonants_reversed = [c for c in reversed_char_list if c not in vowels]
    vowels_reversed = [v for v in reversed_char_list if v in vowels]

