def sum_two_smallest(numbers):
    positive_numbers = []
    for num in numbers:
        if num > 0:
            positive_numbers.append(num)
    first_smallest = min(positive_numbers)
    remaining_numbers = []
    for num in positive_numbers:
        if num != first_smallest:
            remaining_numbers.append(num)
    if not remaining_numbers:
        remaining_numbers = [first_smallest] * 2

    temp_numbers = []
    for num in remaining_numbers:
        temp_numbers.append(num)
    second_smallest = min(temp_numbers)

    numbers_without_smallest = []
    for num in positive_numbers:
        if num > first_smallest:
            numbers_without_smallest.append(num)
    if not numbers_without_smallest:
        numbers_without_smallest = [first_smallest]

    second_smallest_final_list = []
    if numbers_without_smallest:
        for num in numbers_without_smallest:
            if num >= first_smallest:
                second_smallest_final_list.append(num)
        second_smallest_final = min(second_smallest_final_list)
    else:
        second_smallest_final = first_smallest

    return first_smallest + second_smallest_final

