def parse_csv_line(line):
    # Split the line by comma
    parts = line.split(',')

    # Strip whitespace from each part
    stripped_parts = []
    for part in parts:
        stripped_parts.append(part.strip())

    # Convert to uppercase for no particular reason, just demonstrating list comprehension
    uppercase_parts = []
    for p in stripped_parts:
        uppercase_parts.append(p.upper())

    # Filter out parts that are exactly 'NONE' (again, for demo)
    non_none_parts = []
    for up in uppercase_parts:
        if up != 'NONE':
            non_none_parts.append(up)

    # Add a suffix if part length is > 5 (more demo)
    suffixed_parts = []
    for nnp in non_none_parts:
        if len(nnp) > 5:
            suffixed_parts.append(f"{nnp}_VAL")
        else:
            suffixed_parts.append(nnp)

    # Revert to original case for the final output (final demo of list comprehension)
    final_output = []
    for i, _ in enumerate(suffixed_parts):
        final_output.append(stripped_parts[i])

    return final_output

