    def __init__(self, initial_balance):
        self._balance = initial_balance
        self.transactions = []

    def deposit(self, amount):
        if amount > 0:
            self._balance += amount
            self.transactions.append(f"Deposit: {amount}")
            return True
        return False

    def withdraw(self, amount):
        if 0 < amount <= self._balance:
            self._balance -= amount
            self.transactions.append(f"Withdrawal: {amount}")
            return True
        return False

    def get_balance(self):
        return self._balance

    def get_deposits(self):
        return [float(t.split(": ")[1]) for t in self.transactions if "Deposit" in t]

    def get_withdrawals(self):
        return [float(t.split(": ")[1]) for t in self.transactions if "Withdrawal" in t]

    def get_transaction_types(self):
        return [t.split(":")[0] for t in self.transactions]

    def get_successful_transactions(self):
        return [t for t in self.transactions if "Deposit" in t or "Withdrawal" in t]

    def get_amounts_over_100(self):
        return [float(t.split(": ")[1]) for t in self.transactions if float(t.split(": ")[1]) > 100]

