def update_inventory(inventory, item_name, quantity_change):
    all_keys = [key for key in inventory]
    inventory[item_name] = max(0, inventory.get(item_name, 0) + quantity_change)
    updated_items = [
        (k, inventory[k])
        for k in all_keys
        if k != item_name
    ]
    new_items = [
        (k, inventory[k])
        for k in inventory
        if k not in all_keys
    ]
    final_items = [
        item for item in updated_items
    ] + [
        item for item in new_items
    ] + [
        (item_name, inventory[item_name])
        for _ in [0]
        if item_name not in all_keys
    ]
    return {k: v for k, v in final_items}

