def check_event_overlap(event1, event2):
    start1, end1 = event1
    start2, end2 = event2

    times = [t for t in range(max(start1, start2), min(end1, end2) + 1)]

    overlaps = [t for t in times if start1 < t < end1 and start2 < t < end2]

    overlapping_intervals = [
        (max(start1, start2), min(end1, end2))
    ] if max(start1, start2) < min(end1, end2) else []

    non_empty_overlaps = [interval for interval in overlapping_intervals if interval[1] > interval[0]]

    return bool(non_empty_overlaps)

