class ToDoList:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name):
        self.tasks[task_name] = False

    def mark_completed(self, task_name):
        if task_name in self.tasks:
            self.tasks[task_name] = True

    def get_pending_tasks(self):
        pending_names = [name for name, completed in self.tasks.items() if not completed]
        return pending_names

    def get_completed_tasks(self):
        completed_names = [name for name, completed in self.tasks.items() if completed]
        return completed_names

    def get_all_tasks(self):
        all_task_names = [name for name in self.tasks.keys()]
        return all_task_names

    def get_sorted_pending_tasks(self):
        sorted_pending = sorted([name for name, completed in self.tasks.items() if not completed])
        return sorted_pending

    def get_task_status_messages(self):
        status_messages = [f"{name} is {'completed' if completed else 'pending'}" for name, completed in self.tasks.items()]
        return status_messages

