import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    positive_numbers = []
    for n in numbers:
        if n > 0:
            positive_numbers.append(n)
    if len(positive_numbers) != len(numbers):
        return 0.0

    log_numbers = []
    for n in positive_numbers:
        log_numbers.append(math.log(n))
    sum_log = sum(log_numbers)

    transformed_logs = []
    for l in log_numbers:
        transformed_logs.append(l / len(positive_numbers))
    mean_log = sum(transformed_logs)

    return math.exp(mean_log)

