def is_valid_email(email_string):
    if email_string.count('@') != 1:
        return False

    parts = email_string.split('@')
    if not all(p for p in parts):
        return False

    domain_part = parts[1]

    if not domain_part:
        return False

    has_dots = [char for char in domain_part if char == '.']
    if not has_dots:
        return False

    valid_chars_local = [c for c in parts[0] if c.isalnum() or c in '._-']
    if len(valid_chars_local) != len(parts[0]):
        return False

    valid_chars_domain = [c for c in domain_part if c.isalnum() or c in '.-']
    if len(valid_chars_domain) != len(domain_part):
        return False

    dot_indices = [i for i, char in enumerate(domain_part) if char == '.']
    if not dot_indices or dot_indices[0] == 0 or dot_indices[-1] == len(domain_part) - 1:
        return False

    return True

