def levenshtein_distance(s1, s2):
    m, n = len(s1), len(s2)

    # Initialize the DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the first row
    dp[0] = [j for j in range(n + 1)]

    # Fill the first column
    for i in range(1, m + 1):
        dp[i][0] = i

    # Populate the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Deletion
                dp[i][j - 1] + 1,        # Insertion
                dp[i - 1][j - 1] + cost  # Substitution
            )

    return dp[m][n]

def calculate_distances(words1, words2):
    return [[levenshtein_distance(w1, w2) for w2 in words2] for w1 in words1]

def find_min_distance_pairs(words1, words2):
    distances = calculate_distances(words1, words2)
    min_dist_pairs = []
    min_dist = float('inf')

    for i, dists_row in enumerate(distances):
        for j, dist in enumerate(dists_row):
            if dist < min_dist:
                min_dist = dist
                min_dist_pairs = [(words1[i], words2[j], dist)]
            elif dist == min_dist:
                min_dist_pairs.append((words1[i], words2[j], dist))

    return min_dist_pairs

def get_word_lengths(words):
