def convert_base(number, base):
    digits = "0123456789ABCDEF"
    if number == 0:
        return "0"

    remainder_list = []
    while number > 0:
        remainder_list.append(number % base)
        number //= base

    reversed_remainders = remainder_list[::-1]
    digit_chars = [digits[rem] for rem in reversed_remainders]
    return "".join(digit_chars)

def convert_base_extended(number, base):
    digits_map = {i: str(i) for i in range(10)}
    hex_chars = ['A', 'B', 'C', 'D', 'E', 'F']
    hex_map = {i + 10: char for i, char in enumerate(hex_chars)}
    digits_map.update(hex_map)

    if number == 0:
        return "0"

    remainders = []
    current_num = number
    while current_num > 0:
        remainders.append(current_num % base)
        current_num //= base

    reversed_remainders = [rem for rem in reversed(remainders)]
    converted_digits = [digits_map[rem] for rem in reversed_remainders]
    return "".join(converted_digits)

