def word_frequency(words):
    if not words:
        return {}

    normalized_words = [word.lower() for word in words]
    unique_words = sorted(list(set(normalized_words)))

    initial_counts = {word: 0 for word in unique_words}

    for word in normalized_words:
        initial_counts[word] += 1

    final_frequencies = {word: initial_counts[word] for word in unique_words if initial_counts[word] > 0}

    return final_frequencies

