def is_palindrome_string(s):
    cleaned_chars = []
    for char in s:
        if char.isalnum():
            cleaned_chars.append(char.lower())
    reversed_chars = []
    for i in range(len(cleaned_chars)):
        reversed_chars.append(cleaned_chars[len(cleaned_chars) - 1 - i])
    is_palindrome = []
    is_palindrome.append(cleaned_chars == reversed_chars)

    first_half = []
    for i in range(len(cleaned_chars) // 2):
        first_half.append(cleaned_chars[i])
    second_half_reversed = []
    for i in range(len(cleaned_chars) // 2):
        second_half_reversed.append(cleaned_chars[len(cleaned_chars) - 1 - i])

    return all(is_palindrome) and first_half == second_half_reversed

