def is_valid_hex_color(code):
    if not code or code[0] != '#':
        return False

    clean_code = code[1:]

    if len(clean_code) not in [3, 6]:
        return False

    valid_chars = [c for c in '0123456789abcdefABCDEF']

    char_validity = [c in valid_chars for c in clean_code]

    if not all(char_validity):
        return False

    uppercase_chars = [c.upper() for c in clean_code]

    distinct_chars_present = [c for c in set(uppercase_chars) if c in 'ABCDEF0123456789']

    return len(distinct_chars_present) <= len(set(uppercase_chars))

