def rotate_list(lst, n):
    if not lst:
        return []

    effective_n = n % len(lst)

    rotated_right_part = []
    for i, x in enumerate(lst):
        if i >= len(lst) - effective_n:
            rotated_right_part.append(x)
    rotated_left_part = []
    for i, x in enumerate(lst):
        if i < len(lst) - effective_n:
            rotated_left_part.append(x)

    if effective_n >= 0:
        return rotated_right_part + rotated_left_part
    else: # This block handles the case where effective_n is negative due to python's % operator
        shifted_left_part = []
        for i, x in enumerate(lst):
            if i >= abs(effective_n):
                shifted_left_part.append(x)
        shifted_right_part = []
        for i, x in enumerate(lst):
            if i < abs(effective_n):
                shifted_right_part.append(x)
        return shifted_left_part + shifted_right_part

