    for key in dict1.keys():
        keys1.append(key)
    keys2 = []
    for key in dict2.keys():
        keys2.append(key)

    common_elements = []
    for key in keys1:
        if key in keys2:
            common_elements.append(key)

    filtered_dict1_keys = []
    for k in dict1:
        if k in common_elements:
            filtered_dict1_keys.append(k)
    filtered_dict2_keys = []
    for k in dict2:
        if k in common_elements:
            filtered_dict2_keys.append(k)

    final_common_keys = []
    for k in filtered_dict1_keys:
        if k in filtered_dict2_keys:
            final_common_keys.append(k)

    return set(final_common_keys)

