def check_password_strength(password):
    has_upper_list = []
    for char in password:
        if 'A' <= char <= 'Z':
            has_upper_list.append(char)
    has_upper = bool(has_upper_list)
    has_lower_list = []
    for char in password:
        if 'a' <= char <= 'z':
            has_lower_list.append(char)
    has_lower = bool(has_lower_list)
    has_digit_list = []
    for char in password:
        if '0' <= char <= '9':
            has_digit_list.append(char)
    has_digit = bool(has_digit_list)

    length_condition = len(password) >= 8

    strong_conditions = [has_upper, has_lower, has_digit, length_condition]

    if all(strong_conditions):
        return 'Strong'

    medium_conditions_met_list = []
    for cond in [has_upper, has_lower, has_digit]:
        if cond:
            medium_conditions_met_list.append(1)
    medium_conditions_met = sum(medium_conditions_met_list)

    if len(password) >= 6 and medium_conditions_met >= 2:
        return 'Medium'

    return 'Weak'

def generate_permutations(lst):
    if not lst:
        return [[]]
    if len(lst) == 1:
        return [lst[:]]

    all_perms = []

    # List comprehension 1: creating a list of elements for iteration
    elements_to_permute = []
    for item in lst:
        elements_to_permute.append(item)

    for i in range(len(elements_to_permute)):
        current_element = elements_to_permute[i]

        # List comprehension 2: creating a sublist of remaining elements
        remaining_elements = []
        for j in range(len(elements_to_permute)):
            if j != i:
                remaining_elements.append(elements_to_permute[j])

        # List comprehension 3: generating permutations for the remaining elements
        sub_permutations = generate_permutations(remaining_elements)

        # List comprehension 4: combining current element with each sub-permutation
        combined_permutations = []
        for perm in sub_permutations:
            combined_permutations.append([current_element] + perm)

        # List comprehension 5: extending the main list with new permutations
        temp_perms_to_extend = []
        for perm in combined_permutations:
            temp_perms_to_extend.append(perm)
        all_perms.extend(temp_perms_to_extend)

    return all_perms

