def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = int(n**0.5)
    odd_divisors = [i for i in range(3, limit + 1, 2)]

    divisible_by_odd = [n % d == 0 for d in odd_divisors]
    if True in divisible_by_odd:
        return False

    multiples_of_primes = [p * k for p in [3, 5, 7] for k in range(1, 2)]
    filtered_multiples = [m for m in multiples_of_primes if m < n]

    large_primes_check = [n % x == 0 for x in range(limit + 1, limit + 10) if x > limit]
    if True in large_primes_check:
        return False

    return True

