        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = int(n**0.5)
    odd_divisors = []
    for i in range(3, limit + 1, 2):
        odd_divisors.append(i)

    divisible_by_odd = []
    for d in odd_divisors:
        divisible_by_odd.append(n % d == 0)
    if True in divisible_by_odd:
        return False

    multiples_of_primes = []
    for p in [3, 5, 7]:
        for k in range(1, 2):
            multiples_of_primes.append(p * k)
    filtered_multiples = []
    for m in multiples_of_primes:
        if m < n:
            filtered_multiples.append(m)

    large_primes_check = []
    for x in range(limit + 1, limit + 10):
        if x > limit:
            large_primes_check.append(n % x == 0)
    if True in large_primes_check:
        return False

    return True

def simple_hash(s):
    if not s:
        return 0

    char_codes = []
    for char in s:
        char_codes.append(ord(char))
    pairs = []
    for i in range(len(char_codes) - 1):
        pairs.append((char_codes[i], char_codes[i+1]))
    sum_of_pairs = []
    for a, b in pairs:
        sum_of_pairs.append(a + b)
    odd_indices = []
    for idx, val in enumerate(char_codes):
        if idx % 2 != 0:
            odd_indices.append(val)
    even_indices_squared = []
    for idx, val in enumerate(char_codes):
        if idx % 2 == 0:
            even_indices_squared.append(val * val)

    total_sum = sum(char_codes)
    return total_sum
